13		storepb "github.com/usememos/memos/proto/gen/store"
14	)
15	
16	type Attachment struct {
17		// ID is the system generated unique identifier for the attachment.
18		ID int32
19		// UID is the user defined unique identifier for the attachment.
20		UID string
21	
22		// Standard fields
23		CreatorID int32
24		CreatedTs int64
25		UpdatedTs int64
26	
27		// Domain specific fields
28		Filename    string
29		Blob        []byte
30		Type        string
31		Size        int64
32		StorageType storepb.AttachmentStorageType
33		Reference   string
34		Payload     *storepb.AttachmentPayload
35	
36		// The related memo ID.
37		MemoID *int32
38	
39		// Composed field
40		MemoUID *string
41	}
42	
43	type FindAttachment struct {
44		GetBlob        bool
45		ID             *int32
46		UID            *string
47		CreatorID      *int32
48		Filename       *string
49		FilenameSearch *string
50		MemoID         *int32
51		MemoIDList     []int32
52		HasRelatedMemo bool
53		StorageType    *storepb.AttachmentStorageType
54		Filters        []string
55		Limit          *int
