119	func buildComparisonCondition(call *exprv1.Expr_Call, pc parseContext) (Condition, error) {
120		if len(call.Args) != 2 {
121			return nil, errors.New("comparison expects two arguments")
122		}
123		op, err := toComparisonOperator(call.Function)
124		if err != nil {
125			return nil, err
126		}
127	
128		left, err := buildValueExpr(call.Args[0], pc)
129		if err != nil {
130			return nil, err
131		}
132		right, err := buildValueExpr(call.Args[1], pc)
133		if err != nil {
134			return nil, err
135		}
136	
137		// The renderer expects a field/function/accessor on the left. A folded
138		// literal on the left (e.g. now.getMonth() == created_ts.getMonth()) swaps
139		// operands; two literals fold to a constant outcome.
140		if leftLit, ok := left.(*LiteralValue); ok {
141			if rightLit, ok := right.(*LiteralValue); ok {
142				outcome, err := compareLiterals(leftLit.Value, op, rightLit.Value)
143				if err != nil {
144					return nil, err
145				}
146				return &ConstantCondition{Value: outcome}, nil
147			}
148			left, right = right, left
149			op = mirrorComparisonOperator(op)
150		}
151	
152		// If the left side is a field, validate allowed operators.
153		if field, ok := left.(*FieldRef); ok {
154			def, exists := pc.schema.Field(field.Name)
155			if !exists {
156				return nil, errors.Errorf("unknown identifier %q", field.Name)
157			}
158			if def.Kind == FieldKindVirtualAlias {
159				def, exists = pc.schema.ResolveAlias(field.Name)
160				if !exists {
161					return nil, errors.Errorf("invalid alias %q", field.Name)
162				}
163			}
164			if def.AllowedComparisonOps != nil {
165				if _, allowed := def.AllowedComparisonOps[op]; !allowed {
166					return nil, errors.Errorf("operator %s not allowed for field %q", op, field.Name)
167				}
168			}
169		}
170	
171		return &ComparisonCondition{
172			Left:     left,
173			Operator: op,
174			Right:    right,
175		}, nil
176	}
177	
178	// mirrorComparisonOperator flips an operator so swapped operands keep the
179	// original meaning (a < b ⇔ b > a).
180	func mirrorComparisonOperator(op ComparisonOperator) ComparisonOperator {
181		switch op {
182		case CompareLt:
183			return CompareGt
184		case CompareLte:
185			return CompareGte
186		case CompareGt:
187			return CompareLt
188		case CompareGte:
189			return CompareLte
190		default:
191			return op
192		}
193	}
194	
195	// compareLiterals evaluates a comparison whose operands both folded to
196	// constants (e.g. now.getFullYear() >= 2026) into a boolean outcome.
197	func compareLiterals(left any, op ComparisonOperator, right any) (bool, error) {
198		if l, r, ok := asFloats(left, right); ok {
199			switch op {
200			case CompareEq:
201				return l == r, nil
202			case CompareNeq:
203				return l != r, nil
204			case CompareLt:
205				return l < r, nil
206			case CompareLte:
207				return l <= r, nil
208			case CompareGt:
209				return l > r, nil
210			case CompareGte:
211				return l >= r, nil
212			}
213		}
214		if l, ok := left.(string); ok {
215			if r, ok := right.(string); ok {
216				switch op {
217				case CompareEq:
218					return l == r, nil
219				case CompareNeq:
220					return l != r, nil
221				case CompareLt:
222					return l < r, nil
223				case CompareLte:
224					return l <= r, nil
225				case CompareGt:
226					return l > r, nil
227				case CompareGte:
228					return l >= r, nil
229				}
230			}
231		}
232		if l, ok := left.(bool); ok {
233			if r, ok := right.(bool); ok {
234				switch op {
235				case CompareEq:
236					return l == r, nil
237				case CompareNeq:
238					return l != r, nil
239				}
240			}
241		}
242		return false, errors.Errorf("unsupported constant comparison %T %s %T", left, op, right)
243	}
244	
245	// asFloats widens both operands to float64 when each is numeric.
246	func asFloats(left, right any) (float64, float64, bool) {
247		l, lok := toFloat(left)
248		r, rok := toFloat(right)
249		return l, r, lok && rok
250	}
251	
252	func toFloat(v any) (float64, bool) {
253		switch x := v.(type) {
254		case int64:
255			return float64(x), true
256		case float64:
257			return x, true
258		}
259		return 0, false
260	}
