439	func toComparisonOperator(fn string) (ComparisonOperator, error) {
440		switch fn {
441		case "_==_":
442			return CompareEq, nil
443		case "_!=_":
444			return CompareNeq, nil
445		case "_<_":
446			return CompareLt, nil
447		case "_>_":
448			return CompareGt, nil
449		case "_<=_":
450			return CompareLte, nil
451		case "_>=_":
452			return CompareGte, nil
453		default:
454			return "", errors.Errorf("unsupported comparison operator %q", fn)
455		}
456	}
