703	// buildSetCondition desugars ext.Sets() operations over a JSON list field into
704	// existing IR: membership reduces to ElementInCondition, and equivalence adds a
705	// length check. This relies on the list field being a set (no duplicates), which
706	// holds for memo tags.
707	func buildSetCondition(call *exprv1.Expr_Call, pc parseContext) (Condition, error) {
708		if len(call.Args) != 2 {
709			return nil, errors.Errorf("%s expects two arguments", call.Function)
710		}
711	
712		fieldName, err := getIdentName(call.Args[0])
713		if err != nil {
714			return nil, errors.Wrap(err, "set operations require a list field as the first argument")
715		}
716		field, ok := pc.schema.Field(fieldName)
717		if !ok {
718			return nil, errors.Errorf("unknown identifier %q", fieldName)
719		}
720		if field.Kind != FieldKindJSONList {
721			return nil, errors.Errorf("set operations require a list field, got %q", fieldName)
722		}
723	
724		listExpr := call.Args[1].GetListExpr()
725		if listExpr == nil {
726			return nil, errors.New("set operations require a list literal as the second argument")
727		}
728		values := make([]string, 0, len(listExpr.Elements))
729		for _, el := range listExpr.Elements {
730			v, err := getConstValue(el)
731			if err != nil {
732				return nil, errors.Wrap(err, "set operations only support literal string elements")
733			}
734			s, ok := v.(string)
735			if !ok {
736				return nil, errors.New("set operations require string elements")
737			}
738			values = append(values, s)
739		}
740	
741		membership := func(s string) Condition {
742			return &ElementInCondition{Element: &LiteralValue{Value: s}, Field: fieldName}
743		}
744		sizeEquals := func(n int) Condition {
745			return &ComparisonCondition{
746				Left:     &FunctionValue{Name: "size", Args: []ValueExpr{&FieldRef{Name: fieldName}}},
747				Operator: CompareEq,
748				Right:    &LiteralValue{Value: int64(n)},
749			}
750		}
751	
752		switch call.Function {
753		case "sets.contains":
754			if len(values) == 0 {
755				return &ConstantCondition{Value: true}, nil
756			}
757			return combineConditions(LogicalAnd, mapConditions(values, membership)), nil
758		case "sets.intersects":
759			if len(values) == 0 {
760				return &ConstantCondition{Value: false}, nil
761			}
762			return combineConditions(LogicalOr, mapConditions(values, membership)), nil
763		case "sets.equivalent":
764			distinct := distinctStrings(values)
765			if len(distinct) == 0 {
766				return sizeEquals(0), nil
767			}
768			contains := combineConditions(LogicalAnd, mapConditions(distinct, membership))
769			return &LogicalCondition{Operator: LogicalAnd, Left: contains, Right: sizeEquals(len(distinct))}, nil
770		default:
771			return nil, errors.Errorf("unsupported set operation %q", call.Function)
772		}
773	}
774	
775	func mapConditions(values []string, f func(string) Condition) []Condition {
776		conds := make([]Condition, 0, len(values))
777		for _, v := range values {
778			conds = append(conds, f(v))
779		}
780		return conds
781	}
782	
783	func combineConditions(op LogicalOperator, conds []Condition) Condition {
784		result := conds[0]
785		for _, c := range conds[1:] {
786			result = &LogicalCondition{Operator: op, Left: result, Right: c}
787		}
788		return result
789	}
790	
791	func distinctStrings(values []string) []string {
792		seen := make(map[string]bool, len(values))
793		out := make([]string, 0, len(values))
794		for _, v := range values {
795			if !seen[v] {
796				seen[v] = true
797				out = append(out, v)
798			}
799		}
800		return out
801	}
