952	// buildStartsWithPredicate extracts the pattern from t.startsWith("prefix").
953	func buildStartsWithPredicate(call *exprv1.Expr_Call, iterVar string) (PredicateExpr, error) {
954		// Verify the target is the iteration variable
955		if target := call.Target.GetIdentExpr(); target == nil || target.GetName() != iterVar {
956			return nil, errors.Errorf("startsWith target must be the iteration variable %q", iterVar)
957		}
958	
959		if len(call.Args) != 1 {
960			return nil, errors.New("startsWith expects exactly one argument")
961		}
962	
963		prefix, err := getConstValue(call.Args[0])
964		if err != nil {
965			return nil, errors.Wrap(err, "startsWith argument must be a constant string")
966		}
967	
968		prefixStr, ok := prefix.(string)
969		if !ok {
970			return nil, errors.New("startsWith argument must be a string")
971		}
972	
973		return &StartsWithPredicate{Prefix: prefixStr}, nil
974	}
