91	func (r *renderer) renderLogicalCondition(cond *LogicalCondition) (renderResult, error) {
92		left, err := r.renderCondition(cond.Left)
93		if err != nil {
94			return renderResult{}, err
95		}
96		right, err := r.renderCondition(cond.Right)
97		if err != nil {
98			return renderResult{}, err
99		}
100	
101		switch cond.Operator {
102		case LogicalAnd:
103			return combineAnd(left, right), nil
104		case LogicalOr:
105			return combineOr(left, right), nil
106		default:
107			return renderResult{}, errors.Errorf("unsupported logical operator %s", cond.Operator)
108		}
109	}
110	
111	func (r *renderer) renderNotCondition(cond *NotCondition) (renderResult, error) {
112		child, err := r.renderCondition(cond.Expr)
113		if err != nil {
114			return renderResult{}, err
115		}
116	
117		if child.trivial {
118			return renderResult{sql: "1 = 0", unsatisfiable: true}, nil
119		}
120		if child.unsatisfiable {
121			return renderResult{trivial: true}, nil
122		}
123		return renderResult{
124			sql: fmt.Sprintf("NOT (%s)", child.sql),
125		}, nil
126	}
