249	func (r *renderer) renderFunctionComparison(fn *FunctionValue, op ComparisonOperator, right ValueExpr) (renderResult, error) {
250		if fn.Name != "size" {
251			return renderResult{}, errors.Errorf("unsupported function %s in comparison", fn.Name)
252		}
253		if len(fn.Args) != 1 {
254			return renderResult{}, errors.New("size() expects one argument")
255		}
256		fieldArg, ok := fn.Args[0].(*FieldRef)
257		if !ok {
258			return renderResult{}, errors.New("size() argument must be a field")
259		}
260	
261		field, ok := r.schema.Field(fieldArg.Name)
262		if !ok {
263			return renderResult{}, errors.Errorf("unknown field %q", fieldArg.Name)
264		}
265		if field.Kind == FieldKindVirtualAlias {
266			field, ok = r.schema.ResolveAlias(fieldArg.Name)
267			if !ok {
268				return renderResult{}, errors.Errorf("invalid alias %q", fieldArg.Name)
269			}
270		}
271	
272		value, err := expectNumericLiteral(right)
273		if err != nil {
274			return renderResult{}, err
275		}
276	
277		var expr string
278		switch {
279		case field.Kind == FieldKindJSONList:
280			expr = jsonArrayLengthExpr(r.dialect, field)
281		case field.Kind == FieldKindScalar && field.Type == FieldTypeString:
282			expr = stringLengthExpr(r.dialect, field.columnExpr(r.dialect))
283		default:
284			return renderResult{}, errors.Errorf("size() does not support field %q", field.Name)
285		}
286	
287		placeholder := r.addArg(value)
288		return renderResult{
289			sql: fmt.Sprintf("%s %s %s", expr, sqlOperator(op), placeholder),
290		}, nil
291	}
292	
293	// stringLengthExpr returns the character-count expression for a string column.
294	// MySQL's LENGTH counts bytes, so CHAR_LENGTH is used to count characters and
295	// match CEL's size() code-point semantics; SQLite/Postgres LENGTH already counts
296	// characters.
297	func stringLengthExpr(d DialectName, colExpr string) string {
298		if d == DialectMySQL {
299			return fmt.Sprintf("CHAR_LENGTH(%s)", colExpr)
300		}
301		return fmt.Sprintf("LENGTH(%s)", colExpr)
302	}
